// GENERATED SAVED-CONFIG POWER HELPERS - do not edit by hand
// Generated by scripts/build.py from product/v2/card_contract.json.
import type { CardConfig } from "../contracts/types";

export function normalizeSavedConfigPower(
  config: CardConfig, normalizeOptions: (options: string) => string,
): boolean {
  if (config.type !== "power") return false;
    if (!config.label) config.label = "Power Dashboard";
    if (!config.icon) config.icon = "Auto";
    config.icon_on = "Auto";
    config.sensor = "";
    config.unit = "";
    config.type = "power";
    if (config.precision !== "" && config.precision !== "0" && config.precision !== "1" && config.precision !== "2") config.precision = "";
  config.options = normalizeOptions(config.options || "");
  return true;
}
